effect.shader:
float lumaAt(vec2 uv) {
    return dot(texture(inputImg, clamp(uv, 0.0, 1.0)).rgb, vec3(0.299, 0.587, 0.114));
}

void main() {
    vec4 color = texture(inputImg, acScreenNorm);

    float rad = radians(angle);
    vec2 axis = vec2(cos(rad), sin(rad)) * relief * acEscalaDePixel * acTexelSize;

    // A diferença entre os dois lados é a inclinação. Positiva = a superfície
    // sobe na direção da luz, então clareia.
    float slope = (lumaAt(acScreenNorm + axis) - lumaAt(acScreenNorm - axis)) * contrast;

    // Base cinza médio: é o valor neutro que faz a área plana desaparecer, em
    // vez de virar preto. Com "manter a cor" em 1 o relevo é somado à imagem.
    vec3 base = mix(vec3(0.5), color.rgb, keepColor);
    vec3 carved = clamp(base + slope, 0.0, 1.0);

    fragColor = vec4(carved, color.a);
}
